const raw = $input.first().json;
const formResponse = raw.body.form_response;
const answers = formResponse.answers || [];
const hidden = formResponse.hidden || {};
const definition = formResponse.definition || {};
const fieldsDef = definition.fields || [];

// Helper to look up answer by field ref
const byRef = (ref) => answers.find(x => x.field && x.field.ref === ref);

// Build map of field ref / id to question title
const fieldTitleMap = {};
fieldsDef.forEach(f => {
  if (f.ref) fieldTitleMap[f.ref] = f.title;
  if (f.id) fieldTitleMap[f.id] = f.title;
});

// Helper to extract formatted answer value regardless of field type
function getAnswerValue(ans) {
  if (!ans) return '';
  switch (ans.type) {
    case 'choice':
      return ans.choice?.label || '';
    case 'choices':
      return ans.choices?.labels ? ans.choices.labels.join(', ') : '';
    case 'text':
      return ans.text || '';
    case 'email':
      return ans.email || '';
    case 'phone_number':
      return ans.phone_number || '';
    case 'boolean':
      return ans.boolean !== undefined ? (ans.boolean ? 'Yes' : 'No') : '';
    case 'url':
      return ans.url || '';
    case 'number':
      return ans.number !== undefined ? String(ans.number) : '';
    case 'date':
      return ans.date || '';
    default:
      return ans.text || ans.choice?.label || ans.email || ans.phone_number || ans.url || '';
  }
}

// ─── Extract Specific Field Values ────────────────────────────────────
// Question field refs (verified against definition and pinned payload)
const experience      = byRef('9b61d211-b814-42e7-b2e3-2a3bb7aa0888')?.choice?.label || '';
const challenge       = byRef('335bbaef-fd03-4c97-9e04-3c25e1bcce55')?.choice?.label || '';
const coachingRaw     = byRef('8e3e533d-9633-44fb-b343-99b70596bb65');
const coaching        = coachingRaw ? getAnswerValue(coachingRaw) : '';
const firstName       = byRef('5293aeb0-c2dc-4811-9857-8b6199ce60f3')?.text || '';
const lastName        = byRef('4900de89-ce90-4d66-bf30-9985524bb349')?.text || '';

// Phone number: check new ref ('d7b5ac66-dfc4-4a1e-ac58-bb0a02783386') & legacy ref ('477d3c22-0496-4aa7-9649-a60e3e0f9cb5')
const phoneAns        = byRef('d7b5ac66-dfc4-4a1e-ac58-bb0a02783386') || byRef('477d3c22-0496-4aa7-9649-a60e3e0f9cb5');
const phoneRaw        = phoneAns ? (phoneAns.phone_number || phoneAns.text || '') : '';

const emailRaw        = byRef('52751782-6287-4a0e-b66e-4e8698823695')?.email || '';
const budget          = byRef('37de86ae-3f71-4f01-b429-72e34f95ad9e')?.choice?.label || '';

const motivationRaw   = byRef('774f7da2-4717-4efd-a10f-b7bc575ffc74');
const motivation      = motivationRaw ? getAnswerValue(motivationRaw) : '';

const confirmRaw      = byRef('df0591f9-f1b1-4b60-ad50-3599a0554a97');
const commitment      = confirmRaw ? getAnswerValue(confirmRaw) : '';

const calendlyAns     = byRef('c3a60437-0262-46a9-a678-93498570fe3a');
const calendlyUrl     = calendlyAns ? getAnswerValue(calendlyAns) : '';

// ─── Phone Normalisation → E.164 ──────────────────────────────────────
const DEFAULT_COUNTRY_CODE = '44'; // UK

function toE164(input) {
  if (!input) return '';
  let p = input.replace(/[^\d+]/g, '');
  if (p.startsWith('00')) p = '+' + p.slice(2);
  if (p.startsWith('+')) return p;
  if (p.startsWith('0')) return '+' + DEFAULT_COUNTRY_CODE + p.slice(1);
  return '+' + DEFAULT_COUNTRY_CODE + p;
}

const phone = toE164(phoneRaw.trim());
const email = emailRaw.trim().toLowerCase();

// UTM hidden fields
const utmSource   = hidden.utm_source   || '';
const utmMedium   = hidden.utm_medium   || '';
const utmCampaign = hidden.utm_campaign || '';

// Metadata
const isFull  = raw.body.event_type !== 'form_response_partial';
const token   = formResponse.token || '';
const formId  = formResponse.form_id || '';
const landedAt    = formResponse.landed_at || '';
const submittedAt = formResponse.submitted_at || '';
const responseUrl = formResponse.response_url || '';
const now     = new Date().toISOString().replace('T', ' ').substring(0, 19);

// ─── Construct Full Typeform Q&A Notes ────────────────────────────────
const qaList = [];
answers.forEach(ans => {
  const ref = ans.field?.ref;
  const id = ans.field?.id;
  const title = fieldTitleMap[ref] || fieldTitleMap[id] || 'Question';
  const val = getAnswerValue(ans);
  if (val !== '') {
    qaList.push(`• ${title}\n  Answer: ${val}`);
  }
});
const typeformNotes = qaList.length > 0
  ? `📝 Typeform Submission Answers:\n\n${qaList.join('\n\n')}`
  : 'No Typeform answers recorded.';

return [{ json: {
  'Email':                  email,
  'First Name':             firstName,
  'Last Name':              lastName,
  'Full Name':              `${firstName} ${lastName}`.trim(),
  'Phone':                  phone,
  'Experience':             experience,
  'Biggest Challenge':      challenge,
  'Invested in Coaching':   coaching,
  'Budget Answer':          budget,
  'Motivation':             motivation,
  'Commitment Confirmation': commitment,
  'Calendly URL':           calendlyUrl,
  'UTM Source':             utmSource,
  'UTM Medium':             utmMedium,
  'UTM Campaign':           utmCampaign,
  'Typeform Token':         token,
  'Form ID':                formId,
  'Response URL':           responseUrl,
  'Landed At':              landedAt,
  'Submitted At':           submittedAt,
  'Partial Received At':    isFull ? '' : now,
  'Full Received At':       isFull ? now : '',
  'isFull':                 isFull,
  'Typeform Notes':         typeformNotes,
  'All Answers Raw':        JSON.stringify(answers)
} }];

